#!/usr/bin/env python3
"""Refresh the offline bundle and create a complete GitHub Pages source ZIP."""
import json
import sys
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from validate import ROOT, read, validate

catalog = validate()
bundle = {'data/lessons.json': catalog}
for lesson in catalog['lessons']:
    bundle[lesson['file']] = read(ROOT / lesson['file'])
serialized = json.dumps(bundle, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
(ROOT / 'data/lessons.bundle.js').write_text(
    '// Generated by scripts/package.py. Edit the JSON files, then regenerate.\n'
    + 'window.ENGLISH_WORKBOOK = ' + serialized + ';\n', encoding='utf-8')
output = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else ROOT.parent / 'everyday-english.zip'
output.parent.mkdir(parents=True, exist_ok=True)
with ZipFile(output, 'w', ZIP_DEFLATED) as archive:
    for file in sorted(ROOT.rglob('*')):
        relative = file.relative_to(ROOT)
        if file.is_file() and file.resolve() != output and not any(p in {'.git', '__pycache__', 'node_modules', '.openai'} for p in relative.parts) and file.suffix != '.zip':
            archive.write(file, Path('english-practice') / relative)
print(f'Created {output} ({output.stat().st_size:,} bytes)')
